    const fitdf = options.fitdf ?? 0;
    // divided by a power of two (exact; the statistic does not depend on the scale), so that 1e+-300 works. Missing
    // values as R's (acf with na.pass: the products over the pairs both observed; n the number observed; log 107)
    const v0 = standardise(centred(tsInput(x, "boxTest", { missing: "allow", minLength: 2 })));
